            color: var(--text-secondary);
            font-weight: 600;
            font-size: 0.75rem;
            text-transform: uppercase;
            letter-spacing: 0.04em;
        }
        td.number { text-align: right; font-variant-numeric: tabular-nums; }
        tr:hover { background: rgba(255,255,255,0.03); }
